begin;
do $review$
declare p public.hb_policy_versions%rowtype;s public.hb_policy_sources%rowtype;pv integer;
 reviewed timestamptz := '2026-10-10T23:43:00Z';
 new_rules jsonb := $rules$[{"id":"requirement:1","when":[],"effect":"review","reason":"نسخة من نموذج الإعلان — للإعلانات واللوحات والحملات الترويجية.","actions":["collect_or_verify_requirement"],"sourceRefs":["https://dubailand.gov.ae/en/eservices/real-estate-ad-permit/"]},{"id":"requirement:2","when":[],"effect":"review","reason":"مستند موقع الفعالية عند انطباقه — عقد إيجار موقع المعرض أو إطلاق المشروع، أو خطاب عدم ممانعة من الفندق، بحسب نوع التصريح.","actions":["collect_or_verify_requirement"],"sourceRefs":["https://dubailand.gov.ae/en/eservices/real-estate-ad-permit/"]},{"id":"requirement:3","when":[],"effect":"review","reason":"تصميم المنصة أو مستندات الندوة عند انطباقها — للمنصة: تصميم يوضح المقاسات وعقد الموقع. للندوة: حجز القاعة وخطاب الموضوعات.","actions":["collect_or_verify_requirement"],"sourceRefs":["https://dubailand.gov.ae/en/eservices/real-estate-ad-permit/"]},{"id":"requirement:4","when":[],"effect":"review","reason":"قائمة الشركات العقارية المشاركة في المعرض — لتصريح تنظيم المعارض العقارية فقط.","actions":["collect_or_verify_requirement"],"sourceRefs":["https://dubailand.gov.ae/en/eservices/real-estate-ad-permit/"]},{"id":"requirement:5","when":[],"effect":"review","reason":"تختلف المستندات باختلاف نوع الإعلان؛ تعرض بطاقة DLD الرسمية القائمة الدقيقة لكل نوع.","actions":["collect_or_verify_requirement"],"sourceRefs":["https://dubailand.gov.ae/en/eservices/real-estate-ad-permit/"]},{"id":"conditions","when":[],"effect":"review","reason":"شركة أو جهة تحمل ترخيص نشاط عقاري مناسب في دبي.; إذا كان مقدم الطلب وسيطًا عقاريًا، يلزم عقد تسويق مع مالك العقار لأنواع الإعلان المحددة في بطاقة الخدمة.; يجب تقديم مستندات المعرض قبل موعده بشهر على الأقل، ولا يسمح بالبيع أثناء المعرض بل بالحجوزات المبدئية فقط.; يلزم فاصل 30 يومًا بين معارض الدولة نفسها، ولا تُعرض عقارات دبي على الخارطة غير المسجلة لدى إدارة حسابات الضمان.","actions":["review_conditions"],"sourceRefs":["https://dubailand.gov.ae/en/eservices/real-estate-ad-permit/"]},{"id":"fees","when":[],"effect":"review","reason":"تصريح إطلاق مشروع 5000 AED — يضاف 20 درهمًا رسم معرفة وابتكار.; التصاريح الأخرى 1000 AED — يضاف 20 درهمًا رسم معرفة وابتكار.; للمعارض حجز مبدئي غير مسترد بقيمة 10,200 درهم ورسوم مشاركة 1,020 درهم لكل عارض؛ يُخصم رسم الحجز من الرسم النهائي.","actions":["review_fees"],"sourceRefs":["https://dubailand.gov.ae/en/eservices/real-estate-ad-permit/"]},{"id":"duration","when":[],"effect":"review","reason":"يوم عمل واحد.","actions":["review_duration"],"sourceRefs":["https://dubailand.gov.ae/en/eservices/real-estate-ad-permit/"]}]$rules$::jsonb;
begin
 begin
  select * into strict p from public.hb_policy_versions where policy_key='service:dld-real-estate-ad-permit-dubai' and status='active' for update;
  select * into strict s from public.hb_policy_sources where id=any(p.source_ids) and source_url='https://dubailand.gov.ae/en/eservices/real-estate-ad-permit/' and authority_key='dld-rera' and active for update;
 exception when no_data_found then raise notice 'Scoped DLD ad permit absent in clean seed';return;end;
 if p.reviewed_by='official-dld-ad-card-review-2026-10-11' and p.rules=new_rules then return;end if;
 if jsonb_array_length(p.rules)>0 then raise exception 'DLD ad policy changed since scoped review; preserve and re-evaluate existing rules';end if;
 select coalesce(max(version),0)+1 into pv from public.hb_policy_versions where policy_key=p.policy_key and jurisdiction_id is not distinct from p.jurisdiction_id;
 update public.hb_policy_versions set status='retired',effective_until=reviewed where id=p.id;
 insert into public.hb_policy_versions(policy_key,jurisdiction_id,version,effective_from,status,rules,source_ids,reviewed_by,reviewed_at,country_pack_id)
 values(p.policy_key,p.jurisdiction_id,pv,reviewed,'active',new_rules,p.source_ids,'official-dld-ad-card-review-2026-10-11',reviewed,p.country_pack_id);
 update public.hb_policy_sources set last_verified_at=reviewed,last_checked_at=reviewed,last_http_status=200,review_required=false,monitor_failures=0,monitor_error=null,
 metadata=metadata||jsonb_build_object('review_checkpoint','official-dld-ad-card-review-2026-10-11','verification_scope','documents_conditions_fees_duration','verification_state','OFFICIAL_DETAILS_VERIFIED','review_source','https://dubailand.gov.ae/en/eservices/real-estate-ad-permit/') where id=s.id;
 update public.hb_service_bindings set metadata=metadata||jsonb_build_object('governmentDetailsVerified',true,'requirements',$docs$["نسخة من نموذج الإعلان — للإعلانات واللوحات والحملات الترويجية.","مستند موقع الفعالية عند انطباقه — عقد إيجار موقع المعرض أو إطلاق المشروع، أو خطاب عدم ممانعة من الفندق، بحسب نوع التصريح.","تصميم المنصة أو مستندات الندوة عند انطباقها — للمنصة: تصميم يوضح المقاسات وعقد الموقع. للندوة: حجز القاعة وخطاب الموضوعات.","قائمة الشركات العقارية المشاركة في المعرض — لتصريح تنظيم المعارض العقارية فقط.","تختلف المستندات باختلاف نوع الإعلان؛ تعرض بطاقة DLD الرسمية القائمة الدقيقة لكل نوع."]$docs$::jsonb,'review_checkpoint','official-dld-ad-card-review-2026-10-11')
 where policy_key=p.policy_key and service_slug='dld-real-estate-ad-permit-dubai' and active;
 -- Existing workflows, approval requirements, retired contents and source monitoring remain unchanged.
end $review$;
